-- DỮ LIỆU GIẢ LẬP — CHỈ PHỤC VỤ KIỂM THỬ, KHÔNG PHẢI HỒ SƠ THẬT.
-- Chạy highschool_management.sql trước, sau đó chạy file này MỘT LẦN.
-- Dành cho database test mới, chưa có dữ liệu riêng. ID fixture từ 900001 trở lên.
-- Không có DROP/DELETE/TRUNCATE, không tắt FK, không ghi đè bản ghi có sẵn.
-- Nếu gặp lỗi phải ROLLBACK ngay, sửa nguyên nhân rồi chạy lại trong DB test sạch;
-- không tiếp tục đến COMMIT sau lỗi (Workbench có thể tiếp tục các câu còn lại).
-- Email dùng example.com; điện thoại để NULL, địa chỉ ghi rõ giả lập.
-- Mốc xem dữ liệu: 2026-11-03. Lịch học, số tiết là giả định để test.
-- Tài khoản: test_admin, test_giaovu, test_bgh, test_gv01..test_gv12.
-- Mật khẩu chung: Test@12345. Hash BCrypt raw ($2b$, cost 10).
-- Dùng BCryptPasswordEncoder; nếu dùng DelegatingPasswordEncoder cần tiền tố {bcrypt}.
-- test_gv12 bị khóa, giáo viên tương ứng ngừng công tác; dùng để test từ chối truy cập.
-- Vai trò và khối được tra qua mã, không giả định ID danh mục.
SET NAMES utf8mb4 COLLATE utf8mb4_0900_ai_ci;
SET time_zone = '+00:00';
USE `highschool_management`;
START TRANSACTION;

COMMIT;

-- KIỂM TRA SAU IMPORT
SELECT 'HOC_SINH' AS Bang, COUNT(*) AS SoLuong FROM HOC_SINH WHERE MaSoHS LIKE 'TEST-%'
UNION ALL SELECT 'GIAO_VIEN', COUNT(*) FROM GIAO_VIEN WHERE MaSoGV LIKE 'TEST-%'
UNION ALL SELECT 'LOP_HOC', COUNT(*) FROM LOP_HOC WHERE MaLop BETWEEN 900001 AND 900008;
-- Kỳ vọng 62 học sinh, 13 giáo viên, 8 lớp.

-- Danh sách đang học tại ngày tham chiếu; không tính hồ sơ chờ duyệt.
SELECT l.TenLop, hs.MaSoHS, hs.HoTen, xl.TuNgay, xl.DenNgay
FROM XEP_LOP xl JOIN HOC_SINH hs ON hs.MaHS=xl.MaHS
JOIN LOP_HOC l ON l.MaLop=xl.MaLop
WHERE xl.TrangThaiDuyet='DA_DUYET' AND xl.TuNgay <= '2026-11-03'
AND (xl.DenNgay IS NULL OR '2026-11-03' < xl.DenNgay)
ORDER BY l.TenLop,hs.MaSoHS;

-- HS001 có hai bản ghi lịch sử nhưng chỉ một kết quả mỗi môn trong cùng kỳ.
SELECT xl.* FROM XEP_LOP xl JOIN HOC_SINH hs ON hs.MaHS=xl.MaHS WHERE hs.MaSoHS='TEST-HS001' ORDER BY xl.TuNgay;
-- HS060: chưa xếp lớp có hiệu lực, có đề nghị chờ duyệt.
-- HS061: không có liên kết, dùng để test xóa thành công.
-- HS062 đang học 10FULL (sĩ số tối đa 1): dùng test từ chối xếp thêm người.
-- GV013: chưa có phân công/tài khoản, dùng test xóa thành công.
-- 10TEST: lớp trống; HS001: có lịch sử và điểm, test từ chối xóa.
